interface SpotCard {
  _id: string
  name: string
  city: string
  district: string
  address: string
  latitude: number
  longitude: number
  coverImage: string
  coverImageUrl?: string
  rating: number
  playType: string
  playTypeLabel: string
  createdByName: string
  createdByAvatar: string
  createdByAvatarUrl?: string
}

