Component({
  data: {
    _firstShow: true,
    // 模式切换
    activeMode: 'data' as 'data' | 'map',

    // 城市/区选择
    cityIndex: -1,
    districtIndex: -1,
    cityList: guangdongCities.map(c => c.city),
    districtList: [] as string[],
    showCityModal: false,

    // 游玩类型筛选
    filterType: '',
    playTypeList: playTypeList,

    // 数据模式
    spots: [] as SpotCard[],
    loading: false,
    refreshing: false,
    hasMore: true,
    pageSize: 20,
    currentPage: 0,

    // 地图模式
    mapLatitude: 22.5431,
    mapLongitude: 114.0579,
    mapScale: 12,
    markers: [] as any[],
    cityPolygons: [] as any[],
    selectedSpot: null as SpotCard | null,
    showSpotCard: false,
  },

  pageLifetimes: {
    show() {
      if (this.data._firstShow) {
        this.setData({ _firstShow: false })
        return
      }
      this.refreshData()
    },
  },

  lifetimes: {
    attached() {
      this.getCurrentLocation()
    },
  },

  methods: {
    // 获取当前位置
    async getCurrentLocation() {
      try {
        const settingRes = await wx.getSetting()
        if (settingRes.authSetting['scope.userLocation'] === false) {
          wx.showModal({
            title: '需要位置权限',
            content: '请在设置中开启位置权限，以便显示您所在的城市',
            confirmText: '去设置',
            success: (res) => {
              if (res.confirm) wx.openSetting()
            },
          })
          // 默认深圳
          this.setDefaultCity()
          return
        }

        const locationRes = await wx.getLocation({ type: 'gcj02', isHighAccuracy: true })
        const { latitude, longitude } = locationRes

        const geoRes = await new Promise<any>((resolve, reject) => {
          wx.request({
            url: `https://apis.map.qq.com/ws/geocoder/v1/?location=${latitude},${longitude}&key=PRNBZ-7FT3B-KEMUH-JGPZF-G2NA2-5GF2J`,
            success: (res) => resolve(res.data),
            fail: reject,
          })
        })

        if (geoRes.status === 0 && geoRes.result) {
          const { city, district } = geoRes.result.address_component
          const cityIdx = guangdongCities.findIndex(c => c.city === city)
          if (cityIdx >= 0) {
            const districts = guangdongCities[cityIdx].districts
            const districtIdx = districts.indexOf(district)
            this.setData({
              cityIndex: cityIdx,
              districtList: districts,
              districtIndex: districtIdx >= 0 ? districtIdx : -1,
              mapLatitude: latitude,
              mapLongitude: longitude,
            })
            this.loadSpots()
          } else {
            this.setDefaultCity()
          }
        } else {
          this.setDefaultCity()
        }
      } catch (err) {
        console.log('获取位置失败:', err)
        this.setDefaultCity()
      }
    },

    setDefaultCity() {
      this.setData({
        cityIndex: 1, // 深圳
        districtList: guangdongCities[1].districts,
      })
      this.loadSpots()
    },

    // 模式切换
    switchMode() {
      const mode = this.data.activeMode === 'data' ? 'map' : 'data'
      this.setData({ activeMode: mode })
      if (mode === 'map') {
        // 先更新边界
        this.updateCityPolygons()
        // 地图首次渲染需要时间，延迟调整视野
        setTimeout(() => {
          this.adjustMapToCity()
        }, 800)
        // 重新加载数据（reset 分页 + load），确保数据最新
        setTimeout(() => {
          this.refreshData()
        }, 1200)
      }
    },

    // 更新城市/区边界多边形
    updateCityPolygons() {
      const { cityIndex, districtIndex, cityList, districtList } = this.data
      if (cityIndex < 0) return

      const city = cityList[cityIndex]
      let boundaries: Array<{ latitude: number, longitude: number }> | undefined

      // 区级边界优先
      if (districtIndex >= 0 && districtBoundaries[city]) {
        const districtName = districtList[districtIndex]
        boundaries = districtBoundaries[city][districtName]
      }

      // 降级为城市边界
      if (!boundaries || boundaries.length === 0) {
        boundaries = cityBoundaries[city]
      }

      if (boundaries && boundaries.length > 0) {
        this.setData({
          cityPolygons: [{
            points: boundaries,
            strokeWidth: 3,
            strokeColor: '#FF6B35',
            fillColor: 'rgba(255, 107, 53, 0.08)',
            zIndex: 1,
          }]
        })
      } else {
        this.setData({ cityPolygons: [] })
      }
    },

    // 调整地图视野到完整城市/区
    adjustMapToCity() {
      const { cityIndex, districtIndex, cityList, districtList } = this.data
      if (cityIndex < 0) return

      const city = cityList[cityIndex]
      let boundaries: Array<{ latitude: number, longitude: number }> | undefined

      if (districtIndex >= 0 && districtBoundaries[city]) {
        const districtName = districtList[districtIndex]
        boundaries = districtBoundaries[city][districtName]
      }

      if (!boundaries || boundaries.length === 0) {
        boundaries = cityBoundaries[city]
      }

      if (boundaries && boundaries.length > 0) {
        const mapCtx = wx.createMapContext('spotMap')
        mapCtx.includePoints({
          points: boundaries,
          padding: [80, 80, 80, 80]
        })
      }
    },

    // 显示城市选择弹窗
    showCityPicker() {
      this.setData({ showCityModal: true })
    },

    // 隐藏城市选择弹窗
    hideCityPicker() {
      this.setData({ showCityModal: false })
    },

    // 阻止冒泡
    preventTap() {},

    // 城市点击
    onCityTap(e: WechatMiniprogram.TouchEvent) {
      const index = Number(e.currentTarget.dataset.index)
      this.setData({
        cityIndex: index,
        districtIndex: -1,
        districtList: guangdongCities[index].districts,
        showCityModal: false,
        spots: [],
        currentPage: 0,
        hasMore: true,
      })

      // 如果在地图模式，先更新边界和视野，再加载数据
      if (this.data.activeMode === 'map') {
        this.updateCityPolygons()
        // 延迟调整视野，确保地图组件已更新
        setTimeout(() => {
          this.adjustMapToCity()
        }, 500)
        // 再延迟加载数据，避免数据加载影响视野
        setTimeout(() => {
          this.loadSpots()
        }, 1000)
      } else {
        this.loadSpots()
      }
    },

    // 区点击
    onDistrictTap(e: WechatMiniprogram.TouchEvent) {
      const index = Number(e.currentTarget.dataset.index)
      this.setData({
        districtIndex: index,
        showCityModal: false,
        spots: [],
        currentPage: 0,
        hasMore: true,
      })

      // 地图模式：更新区边界和视野
      if (this.data.activeMode === 'map') {
        this.updateCityPolygons()
        setTimeout(() => {
          this.adjustMapToCity()
        }, 500)
        setTimeout(() => {
          this.loadSpots()
        }, 1000)
      } else {
        this.loadSpots()
      }
    },

    // 游玩类型筛选
    onFilterTypeTap(e: WechatMiniprogram.TouchEvent) {
      const type = e.currentTarget.dataset.value || ''
      this.setData({
        filterType: type,
        spots: [],
        currentPage: 0,
        hasMore: true,
      })
      this.loadSpots()
    },

    // 加载数据
    async loadSpots() {
      if (this.data.loading) return
      const { cityIndex, districtIndex, cityList, districtList, currentPage, pageSize, filterType } = this.data
      if (cityIndex < 0) return

      this.setData({ loading: true })

      try {
        const db = wx.cloud.database()
        const city = cityList[cityIndex]

        const where: any = { city }
        if (districtIndex >= 0) {
          where.district = districtList[districtIndex]
        }
        if (filterType) {
          where.playType = filterType
        }

        const query = db.collection('leisureSpots').where(where)
        const countRes = await query.count()
        const total = countRes.total

        if (currentPage * pageSize >= total && currentPage > 0) {
          this.setData({ hasMore: false, loading: false })
          return
        }

        const res = await query
          .orderBy('createdAt', 'desc')
          .skip(currentPage * pageSize)
          .limit(pageSize)
          .get()

        const newSpots = res.data.map((item: any) => ({
          ...item,
          playTypeLabel: playTypeMap[item.playType] || item.playType,
        }))

        // 获取封面图和头像的临时URL（仅处理云存储文件ID）
        const fileIDs: string[] = []
        newSpots.forEach((s: SpotCard) => {
          if (s.coverImage && s.coverImage.startsWith('cloud://')) fileIDs.push(s.coverImage)
          if (s.createdByAvatar && s.createdByAvatar.startsWith('cloud://')) fileIDs.push(s.createdByAvatar)
          // 初始化头像URL（如果是HTTP链接则直接使用）
          if (s.createdByAvatar && !s.createdByAvatar.startsWith('cloud://')) {
            s.createdByAvatarUrl = s.createdByAvatar
          }
        })
        if (fileIDs.length > 0) {
          const tempRes = await wx.cloud.getTempFileURL({ fileList: fileIDs })
          const urlMap: Record<string, string> = {}
          tempRes.fileList.forEach((f: any) => {
            if (f.tempFileURL) urlMap[f.fileID] = f.tempFileURL
          })
          newSpots.forEach((s: SpotCard) => {
            if (s.coverImage && urlMap[s.coverImage]) {
              s.coverImageUrl = urlMap[s.coverImage]
            }
            if (s.createdByAvatar && urlMap[s.createdByAvatar]) {
              s.createdByAvatarUrl = urlMap[s.createdByAvatar]
            }
          })
        }

        this.setData({
          spots: currentPage === 0 ? newSpots : [...this.data.spots, ...newSpots],
          currentPage: currentPage + 1,
          hasMore: newSpots.length === pageSize,
          loading: false,
        })

        // 地图模式下，延迟更新标记，避免影响城市边界视野
        if (this.data.activeMode === 'map') {
          setTimeout(() => {
            this.updateMapMarkers()
          }, 500)
        }
      } catch (err) {
        console.error('加载数据失败:', err)
        this.setData({ loading: false })
        wx.showToast({ title: '加载失败', icon: 'none' })
      }
    },

    // 刷新数据
    refreshData() {
      this.setData({ spots: [], currentPage: 0, hasMore: true, loading: false })
      this.loadSpots()
    },

    // 下拉刷新
    onRefresh() {
      this.setData({ refreshing: true, spots: [], currentPage: 0, hasMore: true })
      this.loadSpots()
      setTimeout(() => {
        this.setData({ refreshing: false })
      }, 1000)
    },

    // 加载更多
    loadMore() {
      if (this.data.hasMore && !this.data.loading) {
        this.loadSpots()
      }
    },

    // 更新地图标记
    updateMapMarkers() {
      const markers = this.data.spots
        .filter(s => s.latitude && s.longitude)
        .map((s, idx) => ({
          id: idx,
          latitude: s.latitude,
          longitude: s.longitude,
          title: s.name,
          width: 24,
          height: 34,
          label: {
            content: s.name,
            color: '#333333',
            fontSize: 12,
            anchorX: 0,
            anchorY: -60,
            bgColor: '#ffffff',
            borderRadius: 8,
            padding: 4,
            borderWidth: 1,
            borderColor: '#FF6B35',
            textAlign: 'center',
          },
        }))

      this.setData({ markers })

      // 标记更新后，强制调整回围栏视图（如果有城市选择）
      if (this.data.activeMode === 'map' && this.data.cityIndex >= 0) {
        setTimeout(() => {
          this.adjustMapToCity()
        }, 100)
      }
    },

    // 地图视野变化（缩放/移动）
    onMapRegionChange(e: WechatMiniprogram.MapRegionChange) {
      // 仅在缩放结束时处理，避免频繁更新
      if (e.type === 'end' && e.causedBy === 'scale') {
        const mapCtx = wx.createMapContext('spotMap')
        mapCtx.getScale({
          success: (res) => {
            const newScale = Math.round(res.scale)
            const { mapScale } = this.data
            // 跨过阈值（14）时才更新
            if ((mapScale >= 14) !== (newScale >= 14)) {
              this.setData({ mapScale: newScale })
              this.updateMapMarkers()
            }
          }
        })
      }
    },

    // 地图标记点击 → 直接跳转详情
    onMarkerTap(e: WechatMiniprogram.MapMarkerTap) {
      const markerId = e.markerId
      const spot = this.data.spots[markerId]
      if (spot) {
        wx.setStorageSync('spotDetailId', spot._id)
        wx.navigateTo({ url: '/pages/leisure/spot-detail/spot-detail' })
      }
    },

    // 地图点击
    onMapTap() {
      this.setData({ showSpotCard: false, selectedSpot: null })
    },

    // 点击卡片查看详情
    goDetail(e: WechatMiniprogram.TouchEvent) {
      const id = e.currentTarget.dataset.id
      wx.setStorageSync('spotDetailId', id)
      wx.navigateTo({ url: '/pages/leisure/spot-detail/spot-detail' })
    },

    // 点击选中的卡片查看详情
    goSelectedDetail() {
      if (this.data.selectedSpot) {
        wx.setStorageSync('spotDetailId', this.data.selectedSpot._id)
        wx.navigateTo({ url: '/pages/leisure/spot-detail/spot-detail' })
      }
    },

    // 回到当前位置
    async moveToCurrentLocation() {
      try {
        const locationRes = await wx.getLocation({ type: 'gcj02', isHighAccuracy: true })
        const { latitude, longitude } = locationRes
        this.setData({
          mapLatitude: latitude,
          mapLongitude: longitude,
          mapScale: 15,
        })
        // 移动地图视野
        const mapCtx = wx.createMapContext('spotMap')
        mapCtx.moveToLocation({ latitude, longitude })
      } catch (err) {
        console.log('获取位置失败:', err)
        wx.showToast({ title: '获取位置失败', icon: 'none' })
      }
    },

    // 发布新去处
    goPublish() {
      wx.navigateTo({ url: '/pages/leisure/spot-edit/spot-edit' })
    },
  },
})
